(()=>{const controls=[...document.querySelectorAll('[data-marine-tool]')];if(!controls.length)return;const descriptions={"marine-bom":{problem:"Manually calculating material quantities across 50–100+ page drawing sets took hours.",solution:"I used computer vision and OCR to turn drawing BOMs into an assembly-aware Excel workbook, reducing hours of manual work to minutes."},"marine-cad":{problem:"Manually nesting ship parts took hours, and inefficient layouts wasted stock material.",solution:"I built a backtracking and dynamic-programming nesting engine in AutoCAD to improve material utilization and reduce hours of layout work to minutes."}};function select(button){const text=descriptions[button.dataset.marineTool];document.getElementById("marine-problem").textContent=text.problem;document.getElementById("marine-solution").textContent=text.solution;for(const control of controls){const open=control===button;control.setAttribute('aria-expanded',String(open));control.querySelector('b').textContent=open?'−':'+';document.getElementById(control.dataset.marineTool).hidden=!open}}controls.forEach((button,i)=>{button.addEventListener('click',()=>select(button));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=event.key==='Home'?0:event.key==='End'?controls.length-1:(i+(event.key==='ArrowRight'?1:-1)+controls.length)%controls.length;controls[index].focus();select(controls[index])})})})();
